<?php require __DIR__ . '/_nav.php'; ?>
<section class="section form-layout"><form class="panel" method="post"><?= csrf_field() ?><h1>Créer un article</h1><label>Titre<input required name="title"></label><label>Extrait<input required name="excerpt"></label><label>Contenu<textarea required name="content"></textarea></label><label>Statut<select name="status"><option value="published">Publié</option><option value="draft">Brouillon</option></select></label><button class="button">Créer</button></form><div><?php foreach ($posts as $post): ?><article class="panel"><strong><?= e($post['title']) ?></strong><p><?= e($post['status']) ?> · <?= e($post['author_email'] ?? '') ?></p><a class="button ghost" href="<?= url('/admin/blog/'.$post['id'].'/modifier') ?>">Modifier</a><form class="inline-form" method="post" action="<?= url('/admin/blog/'.$post['id'].'/supprimer') ?>"><?= csrf_field() ?><button class="danger">Supprimer</button></form></article><?php endforeach; ?></div></section>
